   "ambito": "mundo",
   "procedencia": "directa",
   "sintesis": "La COP31, la cumbre climática de la ONU que se celebra en Turquía, abrió con un llamado de su presidente, Murat Kurum, a que los países se comprometan con el transporte público limpio, los edificios eficientes en el uso de energía y la electricidad asequible. Turquía y Australia, que copresiden la cumbre, impulsan el compromiso “35 X 35”, que busca elevar el uso mundial de electricidad del 21 % al 35 % de aquí a 2035 para reducir las emisiones de gases de efecto invernadero, preferentemente con energía renovable.",
   "puntos": [
    "La COP31, la cumbre climática de la ONU que se celebra en Turquía, abrió con un llamado de su presidente, Murat Kurum, a que los países se comprometan con el transporte público limpio, los edificios eficientes en el uso de energía y la electricidad asequible.",
    "Turquía y Australia, que copresiden la cumbre, impulsan el compromiso “35 X 35”, que busca elevar el uso mundial de electricidad del 21 % al 35 % de aquí a 2035 para reducir las emisiones de gases de efecto invernadero, preferentemente con energía renovable.",
    "La iniciativa se apoya en acuerdos previos: en la COP28 los países pactaron trabajar para triplicar la capacidad renovable y dejar atrás los combustibles fósiles, y la COP29 se centró en el almacenamiento, la modernización de las redes y el financiamiento climático."
   ],
